function generateInfo(title, category) {
  let selectSentences;

  if (category === 1) {
    selectSentences = detailSentences["clothing"];
  } else if (category === 2) {
    selectSentences = detailSentences["pet"];
  } else if (category === 3) {
    selectSentences = detailSentences["glasses"];
  } else {
    selectSentences = detailSentences["shoes"];
  }

  const shuffledSentences = selectSentences.sort(() => 0.5 - Math.random());
  selectSentences = shuffledSentences.slice(0, 7);

  selectSentences.unshift("<h1>" + title + "</h1>");

  return selectSentences.join(" ");
}

// 상세 데이터 생성
function generateRandomData(count) {
  const dataArray = [];

  for (let i = 1; i <= count; i++) {
    // Generate random age distribution that sums to 100
    const ageRandom = Array.from({ length: 4 }, () => Math.random());
    const ageSum = ageRandom.reduce((a, b) => a + b, 0);
    const ageDistr = ageRandom.map((val) => Math.floor((val * 100) / ageSum));
    const ageType5 = 100 - ageDistr.reduce((a, b) => a + b, 0);

    // Generate random gender distribution that sums to 100
    const manPercentage = Math.floor(Math.random() * 101);
    const womanPercentage = 100 - manPercentage;

    // Generate random like and totalSales such that totalSales > like
    const like = Math.floor(Math.random() * 1000000);
    const totalSales = like + Math.floor(Math.random() * 10000);

    // Generate random satisfaction between 0 and 5 with one decimal place
    const satisfaction = (3 + Math.random() * 2).toFixed(1);

    dataArray.push({
      id: i,
      category:product[i-1].category,
      like: like,
      info: generateInfo(product[i-1].title, product[i-1].category.id),
      purchaseStatus: {
        totalSales: totalSales,
        satisfaction: satisfaction,
        age: {
          type1: ageDistr[0],
          type2: ageDistr[1],
          type3: ageDistr[2],
          type4: ageDistr[3],
          type5: ageType5,
        },
        gender: {
          man: manPercentage,
          woman: womanPercentage,
        },
      },
    });
  }

  return dataArray;
}

const dataArray = generateRandomData(100);

// json 형태로 만들되, 다만 key는 문자열 형태로 두지 않는다.
const jsonString = JSON.stringify(dataArray, null, 2);
const formattedString = jsonString.replace(/"([^"]+)":/g, "$1:");
const exportString = `module.exports = {\n  productDetail: ${formattedString}\n};`;

// 파일에 저장
fs.writeFileSync("../productDetailData.js", exportString);

